#!/usr/bin/env node

"use strict";

const fs = require("fs");
const parseArgs = require("minimist");
const Jibo = require("@jibo/jibo-server-client");
const readline = require("readline");
const syslog = require("modern-syslog");

const identity_file = "/var/jibo/identity.json";

let args = process.argv.slice(2);
let argv = parseArgs(args);

function usage() {
    console.log("Usage:", process.argv[1], "[options]");
    console.log("");
    console.log("OPTIONS:");
    console.log("  -h,--help            print this message");
    console.log("  --credentials FILE   path to credentials.json");
    console.log("  --file FILE          logfile to upload");
    console.log("  --maxsize INT        maximum size of a put request");
    console.log("  --maxlogsize INT     maximum size of the log file");
    console.log("  --binary             upload as binary file");
    console.log("  --debug              enable debugging statements");
    console.log("  --kind KIND          specify the kind of log, default: LOG");
}

if (argv.h || argv.help) {
    usage();
    process.exit(0);
}

let debug = false;
if (argv.debug) {
    debug = true;
}

if (!argv.credentials) {
    console.log("ERROR: credentials file not specified!");
    usage();
    process.exit(1);
}

if (!argv.file) {
    console.log("ERROR: file not specified!");
    usage();
    process.exit(1);
}

const logsize = fs.statSync(argv.file).size;

let maxsize = 384*1024; // 384KB
if (argv.maxsize) {
    let ms = parseInt(argv.maxsize);
    if (ms > 0) {
        maxsize = ms;
    } else {
        console.log("ERROR: invalid size", argv.maxsize);
        usage();
        process.exit(1);
    }
}

let maxlogsize = 10*1024*1024; // 10MB
if (argv.maxlogsize) {
    let ms = parseInt(argv.maxlogsize);
    if (ms > 0) {
        maxlogsize = ms;
    } else {
        console.log("ERROR: invalid log size", argv.maxlogsize);
        usage();
        process.exit(1);
    }
}

let log_kind = "LOG";
if (argv.kind){
    log_kind = argv.kind;
}

syslog.init("jibo-log-client", syslog.LOG_PID | syslog.LOG_ODELAY, syslog.LOG_LOCAL0);
syslog.info("Upload log", argv.file, "size", logsize, "bytes");

function get_identity() {
    try {
        let id = JSON.parse(fs.readFileSync(identity_file));
        return id;
    } catch (error) {
        syslog.error("Failed to read identity:", error);
        process.exit(1);
    }
}

if (!fs.existsSync(argv.credentials)) {
    if (logsize >= maxlogsize) {
        syslog.warn("No credentials, but giving up due to max file size");
        process.exit(0);
    } else {
        syslog.warn("ERROR: No credentials!");
        process.exit(1);
    }
}

Jibo.config.loadFromPath(argv.credentials);
let logs = new Jibo.Log();

let identity = get_identity();
function send_log_events(events, callback) {
    let params = {
        events: events,
        deviceId: identity.serial_number
    };
    if (debug) {
        console.log("Sending:", JSON.stringify(params, null, 2));
    }
    logs.putEvents(params, function(error, data) {
        if (error) {
            if (debug) {
                console.log("ERROR:", JSON.stringify(error, null, 2));
            }
            syslog.error("Error putting events:", error.message);
            if (logsize >= maxlogsize) {
                syslog.warn("Giving up due to max file size");
                process.exit(0);
            } else {
                process.exit(1);
            }
        }
        if (debug) {
            console.log("Put events:", JSON.stringify(data, null, 2));
        }
        if (callback) {
            callback(data);
        }
    });
}

// convert a syslog severity number to a Jibo.logEvent level
function severity_to_level(severity) {
    const map = {
        0: "error", // Emergency
        1: "error", // Alert
        2: "error", // Critical
        3: "error", // Error
        4: "warn",  // Warning
        5: "info",  // Notice
        6: "info",  // Informational
        7: "debug", // Debug
    };

    if (map.hasOwnProperty(severity)) {
        return map[severity];
    } else {
        return "info";
    }
}

// convert a syslog severity string to a Jibo.logEvent level
function severitytext_to_level(severity) {
    const map = {
        "emerg": "error",  // Emergency
        "alert": "error",  // Alert
        "crit": "error",   // Critical
        "err": "error",    // Error
        "warning": "warn", // Warning
        "notice": "info",  // Notice
        "info": "info",    // Informational
        "debug": "debug",  // Debug
    };

    if (map.hasOwnProperty(severity)) {
        return map[severity];
    } else {
        return "info";
    }
}

// The following function was cribbed from Glossy
// https://github.com/squeeks/glossy/blob/5c08f66786057cd217583296b65697372c659698/lib/glossy/parse.js#L336
/*
 *  Parse the structured data out of RFC5424 messages
 *  @param {String} msg The STRUCTURED-DATA section
 *  @return {Object} sdStructure parsed structure
 */
function parseStructuredData(msg) {
    var sdStructure = { };

    var state   = 0,
        ignore  = false,
        sdId    = '',
        sdParam = '',
        sdValue = '';

    /*
     * Build the structure using a horrible FSM.
     * The states we cycle are as following:
     *   0 1    2       34       20
     *     [sdID sdParam="sdValue"]
     */
    for(var i = 0; i < msg.length; i++) {
        var c = msg[i];
        switch(state) {
            case 0:  // SD-ELEMENT
                state = (c === '[') ? 1 : 0;
                break;
            case 1: // SD-ID
                if(c != ' ') {
                    sdId += c;
                } else {
                    sdStructure[sdId] = {};
                    state = 2;
                }
                break;
            case 2: // SD-PARAM
                if(c === '=') {
                    sdStructure[sdId][sdParam] = '';
                    state = 3;
                } else if(c === ']') {
                    sdId  = '';
                    state = 0;
                } else if(c != ' '){
                    sdParam += c;
                }
                break;
            case 3: // SD-PARAM/SD-VALUE
                state = c === '"' ? 4 : null; // FIXME Handle rubbish better
                break;
            case 4: // SD-VALUE
                if(c === '\\' && !ignore) {
                    ignore = true;
                } else if(c === '"' && !ignore) {
                    sdStructure[sdId][sdParam] = sdValue;
                    sdParam = '', sdValue = '';
                    state = 2;
                } else {
                    sdValue += c;
                    ignore = false;
                }
                break;
            default:
                break;
        }
    }
    return sdStructure;
}

// Attempt to parse some text as a syslog line and extract properties from it
// Some default properties are returned if the line is not parseable in this way.
function get_log_elements(line) {
    const jibo_regexp = /^([0-9-T:.+Z]+) ([A-Za-z0-9-]+) (.+)\[([0-9-]+),(emerg|alert|crit|err|warning|notice|info|debug)\]: (-|\[.*(?!\\)]+)? ?([PCTJ]|[PCTJ]\.[^\s]+): (.+)$/;
    const sys_regexp = /^([0-9-T:.+]+) ([A-Za-z0-9-]+) (.+)\[([0-9-]+),(emerg|alert|crit|err|warning|notice|info|debug)\]: (-|\[.*(?!\\)]+)? ?(.+)$/;

    let match = line.match(jibo_regexp);
    if (match) {
        const date = new Date(match[1]).getTime();
        const hostname = match[2];
        const program = match[3];
        const pid = match[4] && match[4] !== '-' ? match[4] : null;
        const level = severitytext_to_level(match[5]);
        const structuredData = match[6] && match[6] !== '-'
            ? parseStructuredData(match[6])
            : null;
        const namespace = match[7];
        const message = match[8].trim();
        return {
            date,
            hostname,
            program,
            pid,
            level,
            structuredData,
            namespace,
            message,
        };
    } else {
        match = line.match(sys_regexp);
        if (match) {
            const date = new Date(match[1]).getTime();
            const hostname = match[2];
            const program = match[3];
            let pid = match[4];
            if (pid == "-") {
                pid = null;
            }
            const level = severitytext_to_level(match[5]);
            const structuredData = match[6] && match[6] !== '-'
                ? parseStructuredData(match[6])
                : null;
            const message = match[7].trim();
            return {
                date: date,
                hostname: hostname,
                program: program,
                pid: pid,
                level: level,
                namespace: null,
                message: message
            };
        } else {
            return {
                date: new Date().getTime(),
                hostname: identity.name,
                program: "jibo-log-client",
                pid: null,
                level: "info",
                namespace: null,
                message: line
            };
        }
    }
}

function do_log_events() {
    let fstream = fs.createReadStream(argv.file);

    let lineReader = readline.createInterface({
        input: fstream
    });

    let events = [];
    let events_length = 0;

    fstream.on("end", function() {
        lineReader.close();
        send_log_events(events, function() {
            syslog.info("Finished!");
        });
    });

    lineReader.on("line", function(line) {
        if (debug) {
            console.log("Got line:", line);
        }
        const elements = get_log_elements(line);
        let evt = {
            created: elements.date,
            level: elements.level,
            message: elements.message,
            payload: {
                kind: log_kind,
                hostname: elements.hostname,
                program: elements.program,
                pid: elements.pid,
                namespace: elements.namespace,
                structuredData: elements.structuredData,
            }
        };
        events.push(evt);
        events_length += JSON.stringify(evt).length;
        if (events_length > maxsize) {
            if (debug) {
                console.log("Events length", events_length, ", sending...");
            }
            lineReader.pause();
            send_log_events(events, function() {
                if (debug) {
                    console.log("Done send");
                }
                lineReader.resume();
            });
            events = [];
            events_length = 0;
        }
    });
}

function do_log_binary() {
    let fstream = fs.createReadStream(argv.file);

    const now = Date.now();

    const trackingId = "jibo_log_client_" + now;

    let params = {
        body: fstream,
        trackingId: trackingId,
    };
    logs.putBinary(params, function(error, data) {
        if (error) {
            syslog.error("Error putting binary:", error.message);
            if (logsize >= maxlogsize) {
                syslog.warn("Giving up due to max file size");
                process.exit(0);
            } else {
                process.exit(1);
            }
        }
        if (debug) {
            console.log("Put binary:", JSON.stringify(data, null, 2));
        }
        let evt = {
            created: now,
            message: "LOG_UPLOAD: " + identity.name,
            payload: {
                url: data.url
            }
        }
        logs.putEvents({
            trackingId: trackingId,
            deviceId: identity.serial_number,
            events: [evt]
        }, function(error, data) {
            if (error) {
                if (debug) {
                    console.log("ERROR:", JSON.stringify(error, null, 2));
                }
                syslog.error("Error putting events:", error.message);
                if (logsize >= maxlogsize) {
                    syslog.warn("Giving up due to max file size");
                    process.exit(0);
                } else {
                    process.exit(1);
                }
            }
            if (debug) {
                console.log("Put events:", JSON.stringify(data, null, 2));
            }
        });
    });
}

if (argv.binary) {
    do_log_binary();
} else {
    do_log_events();
}
